contract InvMutTest {
    C c;
    uint public callCount;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory tos, uint[] memory vs) public returns (bool) {
        require(tos.length > 0);
        require(tos.length == vs.length);
        callCount = 0;
        bool ok = c.transfer(from, address(this), tos, vs);
        assert(ok && callCount == tos.length);
        return ok;
    }

    fallback() external payable {
        callCount++;
        bytes memory ret = abi.encodePacked(uint256(1));
        assembly { return(add(ret, 32), 32) }
    }

    receive() external payable {}
}

