contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address from, address to, uint v) public {
        // Phase 1: empty destination list must revert
        address[] memory emptyTos = new address[](0);
        uint[] memory emptyVs = new uint[](0);
        bool revertedOnEmpty;
        try c.transfer(from, address(0), emptyTos, emptyVs) {
            revertedOnEmpty = false;
        } catch {
            revertedOnEmpty = true;
        }

        // Phase 2: single destination, token address with no code (call succeeds)
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vs = new uint[](1);
        vs[0] = v;
        bool ok = c.transfer(from, address(0), tos, vs);

        assert(revertedOnEmpty && ok);
    }

    receive() external payable {}
}

